PVOID volatile g_windowHandle = nullptr;

HWND LoadIslandWindowHandle() {
    return reinterpret_cast<HWND>(InterlockedCompareExchangePointer(
        &g_windowHandle, nullptr, nullptr));
}

void StoreIslandWindowHandle(HWND hwnd) {
    InterlockedExchangePointer(&g_windowHandle, reinterpret_cast<PVOID>(hwnd));
}
HANDLE g_workerThread = nullptr;
