HANDLE g_stopEvent = nullptr;

bool IsShutdownRequested() {
    HANDLE stop = g_stopEvent;
    return stop && WaitForSingleObject(stop, 0) == WAIT_OBJECT_0;
}

// Cancellation is best-effort; workers still must exit and be joined before the DLL unloads.
void RequestComCallCancellation(HANDLE thread, DWORD threadId, const wchar_t* name) {
    if (!thread || !threadId || WaitForSingleObject(thread, 0) != WAIT_TIMEOUT) return;

    // CoCancelCall is an OLE API. Ensure this callback thread has COM initialized if needed.
    const HRESULT initHr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
    const bool initializedHere = SUCCEEDED(initHr);
    const HRESULT cancelHr = CoCancelCall(threadId, 0);
    // CoCancelCall may return RPC_E_SERVERCALL_RETRYLATER (0x8001011E)
    // when the target thread is not accepting cancellation at shutdown.
    // This is non-fatal: worker termination is verified by waitAndClose below.
    if (FAILED(cancelHr) && cancelHr != RPC_E_CALL_COMPLETE && cancelHr != RPC_E_CALL_CANCELED &&
        cancelHr != CO_E_CANCEL_DISABLED && cancelHr != E_NOINTERFACE &&
        static_cast<DWORD>(cancelHr) != 0x8001011E) {
        Wh_Log(L"Merlin shutdown: CoCancelCall(%s, thread %lu) failed: 0x%08X",
               name, threadId, static_cast<DWORD>(cancelHr));
    }
    if (initializedHere) CoUninitialize();
}

