// Reference geometry is read from the supplied editable ORA artboard (2048 x 684).
// The artboard is mapped into the existing 420 x 140 logical music-card coordinate space.
constexpr float kMusicReferenceWidth = 2048.0f;
constexpr float kMusicReferenceHeight = 684.0f;
constexpr float kMusicLogicalWidth = 420.0f;
constexpr float kMusicLogicalHeight = 140.0f;
constexpr float MusicDesignX(float artboardX) {
    return artboardX * kMusicLogicalWidth / kMusicReferenceWidth;
}
constexpr float MusicDesignY(float artboardY) {
    return artboardY * kMusicLogicalHeight / kMusicReferenceHeight;
}

// Implemented below the expanded-size globals, where actual island dimensions are available.
float MusicCenter(int index);

float g_width = kClosedWidth;
float g_height = kClosedHeight;

// Coordinates below are measured from the supplied full-width Photoshop reference,
// whose island outline spans almost the complete 2045 x 678 canvas. The previous
// implementation mapped every layer against the whole 2048px artboard and a fixed
// 420px width; that compressed the controls toward the left whenever island width
// was scaled and placed the album/title at positions from a different ORA preview.
constexpr float kMusicReferenceLeft = 10.0f;
constexpr float kMusicReferencePanelWidth = 2035.0f;
constexpr float kMusicReferencePanelHeight = 659.0f;
float MusicReferenceX(float x) {
    return (x - kMusicReferenceLeft) * g_width / kMusicReferencePanelWidth;
}
float MusicReferenceDeltaX(float width) {
    return width * g_width / kMusicReferencePanelWidth;
}
float MusicReferenceY(float y) {
    return y * g_height / kMusicReferencePanelHeight;
}
float MusicReferenceDeltaY(float height) {
    return height * g_height / kMusicReferencePanelHeight;
}
float MusicControlsYOffset() {
    const float lyricsT = std::clamp(g_lyricsT, 0.0f, 1.0f);
    return MusicReferenceY(505.0f) + (113.0f * kUiScale - MusicReferenceY(505.0f)) * lyricsT;
}
float MusicTrackXOffset() {
    const float lyricsT = std::clamp(g_lyricsT, 0.0f, 1.0f);
    return MusicReferenceX(716.0f) + (43.0f * kUiScale - MusicReferenceX(716.0f)) * lyricsT;
}
float MusicTrackYOffset() {
    const float lyricsT = std::clamp(g_lyricsT, 0.0f, 1.0f);
    return MusicReferenceY(373.0f) + (96.0f * kUiScale - MusicReferenceY(373.0f)) * lyricsT;
}
float MusicTrackWidth() {
    const float lyricsT = std::clamp(g_lyricsT, 0.0f, 1.0f);
    return MusicReferenceDeltaX(1002.0f) + (72.0f * kUiScale - MusicReferenceDeltaX(1002.0f)) * lyricsT;
}

// Centers correspond to the four requested controls in the Photoshop reference:
// previous, play/pause, next, lyrics. The removed shuffle control is not reserved.
// Returning physical drawing offsets keeps positions and hit rectangles in the same space.
float MusicCenter(int index) {
    const float from[] = {MusicReferenceX(985.0f), MusicReferenceX(1205.0f),
                          MusicReferenceX(1425.0f), MusicReferenceX(1635.0f)};
    const float to[] = {58.0f * kUiScale, 91.0f * kUiScale,
                        124.0f * kUiScale, 25.0f * kUiScale};
    if (index < 0 || index >= 4) return 0.0f;
    return from[index] + (to[index] - from[index]) * std::clamp(g_lyricsT, 0.0f, 1.0f);
}

