// Window placement: monitor index is sorted left-to-right, then top-to-bottom.
// Presets 0..8 form a 3x3 grid; 9 stores a freely dragged custom position.
// When locked, dragging and placement preset/monitor changes are disabled.
bool g_positionLocked = false;
int g_positionMonitorIndex = 0;
int g_settingsMonitorIndex = 0;  // Keep the settings panel on its current monitor while choosing a destination.
int g_positionPreset = 1;  // Preserve the original top-centre position by default.
int g_customXPermille = 5000;  // Island centre as a fraction of the monitor width.
int g_customYPermille = 0;     // Island top as a fraction of the monitor's usable height.
int g_windowScreenX = 0;
int g_windowScreenY = 0;
