void UpdateAlbumAnimationState(ULONGLONG now) {
    const std::wstring key = g_media.available
        ? (g_media.title + L"\n" + g_media.artist + L"\n" + g_media.artKey)
        : std::wstring(L"__no_media__");
    if (key != g_lastAlbumAnimationKey) {
        g_lastAlbumAnimationKey = key;
        g_albumAnimationStart = now;
    }
}

float GetAlbumAnimationScale(ULONGLONG now) {
    const ULONGLONG age = (g_albumAnimationStart != 0 && now >= g_albumAnimationStart)
        ? now - g_albumAnimationStart : 520ULL;
    const float t = std::clamp(static_cast<float>(age) / 520.0f, 0.0f, 1.0f);
    const float ease = t * t * (3.0f - 2.0f * t);
    const float introScale = 0.925f + 0.075f * ease;
    const float breathe = (g_media.available && g_media.playing)
        ? 0.0065f * std::sin(static_cast<float>(now % 2500ULL) / 2500.0f * 2.0f * kPi)
        : 0.0f;
    const ULONGLONG beatTick = g_audioBeatTick.load(std::memory_order_acquire);
    const ULONGLONG beatAge = (beatTick != 0 && now >= beatTick) ? now - beatTick : 9999ULL;
    const float beatStrength = beatAge < 220ULL
        ? std::clamp(g_audioBeatStrength.load(std::memory_order_relaxed), 0.0f, 1.0f) *
          (1.0f - static_cast<float>(beatAge) / 220.0f) : 0.0f;
    const float beatScale = g_media.available && g_media.playing ? beatStrength * 0.012f : 0.0f;
    return std::clamp(introScale + breathe + beatScale, 0.91f, 1.025f);
}

COLORREF EyePickerHsvToColor(float hue, float saturation, float value) {
    hue = std::fmod(hue, 360.0f);
    if (hue < 0.0f) hue += 360.0f;
    saturation = std::clamp(saturation, 0.0f, 1.0f);
    value = std::clamp(value, 0.0f, 1.0f);
    const float chroma = value * saturation;
    const float h6 = hue / 60.0f;
    const float x = chroma * (1.0f - std::fabs(std::fmod(h6, 2.0f) - 1.0f));
    float r = 0.0f;
    float g = 0.0f;
    float b = 0.0f;
    if (h6 < 1.0f) { r = chroma; g = x; }
    else if (h6 < 2.0f) { r = x; g = chroma; }
    else if (h6 < 3.0f) { g = chroma; b = x; }
    else if (h6 < 4.0f) { g = x; b = chroma; }
    else if (h6 < 5.0f) { r = x; b = chroma; }
    else { r = chroma; b = x; }
    const float m = value - chroma;
    return RGB(static_cast<BYTE>(std::round((r + m) * 255.0f)),
               static_cast<BYTE>(std::round((g + m) * 255.0f)),
               static_cast<BYTE>(std::round((b + m) * 255.0f)));
}

void SyncEyePickerFromColor() {
    const float r = GetRValue(g_customEyeColor) / 255.0f;
    const float g = GetGValue(g_customEyeColor) / 255.0f;
    const float b = GetBValue(g_customEyeColor) / 255.0f;
    const float maximum = (std::max)(r, (std::max)(g, b));
    const float minimum = (std::min)(r, (std::min)(g, b));
    const float delta = maximum - minimum;
    g_eyePickerValue = maximum;
    g_eyePickerSaturation = maximum <= 0.0001f ? 0.0f : delta / maximum;
    if (delta > 0.0001f) {
        if (maximum == r) g_eyePickerHue = 60.0f * std::fmod((g - b) / delta, 6.0f);
        else if (maximum == g) g_eyePickerHue = 60.0f * (((b - r) / delta) + 2.0f);
        else g_eyePickerHue = 60.0f * (((r - g) / delta) + 4.0f);
        if (g_eyePickerHue < 0.0f) g_eyePickerHue += 360.0f;
    }
}

