std::wstring TranslateUiText(const std::wstring& source, int depth = 0) {
    const int language = std::clamp(g_uiLanguage, 0, 9);
    if (language == 0 || source.empty() || depth > 4) return source;

    // Exact translations always win. This covers complete labels and descriptions.
    for (const auto& entry : kUiTranslations) {
        if (source == entry.source) return entry.values[language];
    }

    // Dynamic labels (for example "Ekran 1 / 2" or "Seçili konum: Serbest konum")
    // are built from a translated prefix plus a value supplied at runtime.
    const UiTranslationEntry* bestPrefix = nullptr;
    size_t bestPrefixLength = 0;
    for (const auto& entry : kUiTranslations) {
        const size_t length = std::wcslen(entry.source);
        if (length < 3 || length <= bestPrefixLength || length >= source.size()) continue;
        if (source.compare(0, length, entry.source) == 0) {
            bestPrefix = &entry;
            bestPrefixLength = length;
        }
    }
    if (bestPrefix) {
        return std::wstring(bestPrefix->values[language]) +
               TranslateUiText(source.substr(bestPrefixLength), depth + 1);
    }

    // Translate known suffixes inside composed hardware values without touching
    // model names, serial numbers, measurements, paths or other machine data.
    std::wstring result = source;
    for (const auto& entry : kUiTranslations) {
        const size_t length = std::wcslen(entry.source);
        if (length < 4 || entry.source[0] != L' ') continue;
        size_t pos = 0;
        while ((pos = result.find(entry.source, pos)) != std::wstring::npos) {
            result.replace(pos, length, entry.values[language]);
            pos += std::wcslen(entry.values[language]);
        }
    }
    return result;
}

void DrawLabel(Graphics& graphics, const std::wstring& text, float x, float y,
              float size, Color color, bool bold = false) {
    const std::wstring localized = TranslateUiText(text);
    FontFamily family(L"Segoe UI");
    Font font(&family, size * kUiScale, bold ? FontStyleBold : FontStyleRegular, UnitPixel);
    SolidBrush brush(color);
    graphics.DrawString(localized.c_str(), static_cast<INT>(localized.size()), &font,
                        PointF(x, y), &brush);
}

void DrawIslandScaledLabel(Graphics& graphics, const std::wstring& text,
                            float x, float y, float size, Color color,
                            bool bold = false) {
    // Menu content has a fixed layout scale. The size slider affects only the compact waiting island.
    DrawLabel(graphics, text, x, y, size, color, bold);
}

void DrawCenteredText(Graphics& graphics, const std::wstring& text, float centerX,
                      float y, float size, Color color, bool bold = false) {
    const std::wstring localized = TranslateUiText(text);
    FontFamily family(L"Segoe UI");
    Font font(&family, size * kUiScale, bold ? FontStyleBold : FontStyleRegular, UnitPixel);
    SolidBrush brush(color);
    RectF bounds;
    graphics.MeasureString(localized.c_str(), static_cast<INT>(localized.size()), &font,
                           PointF(0.0f, 0.0f), &bounds);
    graphics.DrawString(localized.c_str(), static_cast<INT>(localized.size()), &font,
                        PointF(centerX - bounds.Width / 2.0f, y), &brush);
}

void DrawRoundedRect(Graphics& graphics, const RectF& rect, float radius, Brush& brush) {
    GraphicsPath path;
    const float d = radius * 2.0f;
    path.AddArc(rect.X, rect.Y, d, d, 180.0f, 90.0f);
    path.AddArc(rect.GetRight() - d, rect.Y, d, d, 270.0f, 90.0f);
    path.AddArc(rect.GetRight() - d, rect.GetBottom() - d, d, d, 0.0f, 90.0f);
    path.AddArc(rect.X, rect.GetBottom() - d, d, d, 90.0f, 90.0f);
    path.CloseFigure();
    graphics.FillPath(&brush, &path);
}

bool CursorOverIsland() {
    POINT cursor{};
    if (!GetCursorPos(&cursor)) {
        return false;
    }
    const float localX = static_cast<float>(cursor.x - g_windowScreenX) - static_cast<float>(kCanvasWidth) / 2.0f;
    const float localY = static_cast<float>(cursor.y - g_windowScreenY) - g_dropY;
    const float hitWidth = g_width;
    const float hitHeight = g_height;
    return std::fabs(localX) <= hitWidth / 2.0f && localY >= 0.0f && localY <= hitHeight;
}

struct ControlButtonRects {
    RectF settings;
    RectF close;
};

RectF GetSettingsPanelRect() {
    // Reserve the top strip for the visible waiting-eye capsule.
    // The compact island remains above settings instead of being covered by the panel.
    const float panelTop = kSettingsPanelTop + kClosedHeight;
    return RectF((kCanvasWidth - kSettingsPanelWidth) / 2.0f,
                 panelTop, kSettingsPanelWidth, kSettingsPanelHeight);
}

ControlButtonRects GetControlButtonRects() {
    ControlButtonRects rects{};
    if (g_settingsOpen) {
        // In settings mode the controls belong to the panel header, not the small island.
        const RectF panel = GetSettingsPanelRect();
        constexpr float size = 42.0f;
        constexpr float gap = 6.0f;
        constexpr float margin = 8.0f;
        constexpr float topInset = 7.0f;
        const float top = panel.Y + topInset;
        rects.close = RectF(panel.GetRight() - margin - size, top, size, size);
        rects.settings = RectF(rects.close.X - gap - size, top, size, size);
    } else {
        const float right = kCanvasWidth / 2.0f + g_width / 2.0f;
        const float S = kUiScale;
        // These values correspond to the settings/close layers in the supplied ORA artboard.
        const float size = MusicDesignX(85.0f) * S;
        const float gap = MusicDesignX(17.0f) * S;
        const float margin = MusicDesignX(2048.0f - 1987.0f) * S;
        const float top = MusicDesignY(13.0f) * S;
        rects.close = RectF(right - margin - size, top, size, size);
        rects.settings = RectF(rects.close.X - gap - size, top, size, size);
    }
    return rects;
}

bool PointInRect(float x, float y, const RectF& rect) {
    return x >= rect.X && x <= rect.GetRight() &&
           y >= rect.Y && y <= rect.GetBottom();
}

// Settings controls use a shared visual language: soft elevation, a subtle outline,
// rounded corners and a restrained blue accent on hover/selection.
bool IsCursorOverUiRect(const RectF& rect) {
    if (!g_settingsOpen || rect.Width <= 0.0f || rect.Height <= 0.0f) return false;
    POINT cursor{};
    if (!GetCursorPos(&cursor)) return false;
    const float x = static_cast<float>(cursor.x - g_windowScreenX);
    const float y = static_cast<float>(cursor.y - g_windowScreenY);
    return PointInRect(x, y, rect);
}

void DrawRoundedOutline(Graphics& graphics, const RectF& rect, float radius, Pen& pen) {
    if (rect.Width <= 0.0f || rect.Height <= 0.0f) return;
    radius = (std::max)(1.0f, (std::min)(radius, (std::min)(rect.Width, rect.Height) * 0.5f));
    const float d = radius * 2.0f;
    GraphicsPath path;
    path.AddArc(rect.X, rect.Y, d, d, 180.0f, 90.0f);
    path.AddArc(rect.GetRight() - d, rect.Y, d, d, 270.0f, 90.0f);
    path.AddArc(rect.GetRight() - d, rect.GetBottom() - d, d, d, 0.0f, 90.0f);
    path.AddArc(rect.X, rect.GetBottom() - d, d, d, 90.0f, 90.0f);
    path.CloseFigure();
    graphics.DrawPath(&pen, &path);
}

// Dark glass settings card with a restrained warm-gold outline.
void DrawSettingsCard(Graphics& graphics, const RectF& rect, float opacity, float radius = 13.0f) {
    if (rect.Width <= 0.0f || rect.Height <= 0.0f || opacity <= 0.01f) return;
    const float S = kUiScale;
    // Soft gold halo outside; the actual card face stays black.
    Pen halo(MakeColor(Alpha(10.0f, opacity), 238, 190, 101), 4.0f * S);
    DrawRoundedOutline(graphics, rect, radius * S, halo);
    SolidBrush fill(MakeColor(Alpha(244.0f, opacity), 7, 7, 6));
    DrawRoundedRect(graphics, rect, radius * S, fill);
    Pen edge(MakeColor(Alpha(112.0f, opacity), 153, 116, 48), 0.85f * S);
    DrawRoundedOutline(graphics, rect, radius * S, edge);
}

void DrawModernButtonSurface(Graphics& graphics, const RectF& rect, float opacity,
                             bool selected, bool hovered, bool pressed,
                             bool compact = false) {
    if (rect.Width <= 0.0f || rect.Height <= 0.0f || opacity <= 0.01f) return;
    const float S = kUiScale;
    const float radius = (std::min)(rect.Height * (compact ? 0.30f : 0.28f),
                                    compact ? 7.0f * S : 10.0f * S);
    const float pressOffset = pressed ? 1.2f * S : 0.0f;
    const RectF face(rect.X, rect.Y + pressOffset, rect.Width,
                     (std::max)(1.0f, rect.Height - pressOffset));
    const ULONGLONG now = GetTickCount64();
    const float pulse = 0.5f + 0.5f * std::sin(static_cast<float>(now % 1600ULL) * (2.0f * kPi / 1600.0f));
    const bool glowing = hovered && g_visualEffectsEnabled;

    if (!compact) {
        SolidBrush shadow(MakeColor(Alpha(pressed ? 3.0f : (hovered ? 27.0f : 19.0f), opacity), 0, 0, 0));
        DrawRoundedRect(graphics, RectF(face.X, face.Y + 1.2f * S, face.Width, face.Height), radius, shadow);
    }
    // Layered, warm-gold halo adapted from the CodeFronts neon-pulse button.
    if (glowing || selected) {
        const float base = glowing ? (8.0f + 6.0f * pulse) : 3.5f;
        const float padOuter = (glowing ? 3.0f : 1.2f) * S;
        SolidBrush outerGlow(MakeColor(Alpha(base, opacity), 232, 187, 91));
        DrawRoundedRect(graphics, RectF(face.X - padOuter, face.Y - padOuter,
                                        face.Width + 2.0f * padOuter, face.Height + 2.0f * padOuter),
                        radius + padOuter, outerGlow);
        if (glowing) {
            const float midPad = 1.7f * S;
            SolidBrush middleGlow(MakeColor(Alpha(5.0f + 3.0f * pulse, opacity), 247, 200, 110));
            DrawRoundedRect(graphics, RectF(face.X - midPad, face.Y - midPad,
                                            face.Width + 2.0f * midPad, face.Height + 2.0f * midPad),
                            radius + midPad, middleGlow);
        }
        SolidBrush innerGlow(MakeColor(Alpha(glowing ? (10.0f + 7.0f * pulse) : 5.0f, opacity), 255, 204, 115));
        DrawRoundedRect(graphics, RectF(face.X - 0.7f * S, face.Y - 0.7f * S,
                                        face.Width + 1.4f * S, face.Height + 1.4f * S),
                        radius + 0.7f * S, innerGlow);
    }

    Color topColor;
    Color bottomColor;
    Color edgeColor;
    if (pressed) {
        topColor = MakeColor(Alpha(237.0f, opacity), 62, 45, 19);
        bottomColor = MakeColor(Alpha(240.0f, opacity), 34, 26, 13);
        edgeColor = MakeColor(Alpha(235.0f, opacity), 250, 199, 103);
    } else if (selected) {
        topColor = MakeColor(Alpha(235.0f, opacity), 47, 37, 19);
        bottomColor = MakeColor(Alpha(238.0f, opacity), 28, 23, 14);
        edgeColor = MakeColor(Alpha(238.0f, opacity), 238, 192, 103);
    } else if (hovered) {
        topColor = MakeColor(Alpha(235.0f, opacity), 37, 31, 21);
        bottomColor = MakeColor(Alpha(236.0f, opacity), 20, 18, 14);
        edgeColor = MakeColor(Alpha(hovered ? (173.0f + 26.0f * pulse) : 150.0f, opacity), 218, 174, 89);
    } else {
        topColor = MakeColor(Alpha(226.0f, opacity), 21, 20, 17);
        bottomColor = MakeColor(Alpha(232.0f, opacity), 13, 13, 12);
        edgeColor = MakeColor(Alpha(112.0f, opacity), 104, 80, 42);
    }

    LinearGradientBrush faceFill(PointF(face.X, face.Y), PointF(face.X, face.GetBottom()), topColor, bottomColor);
    DrawRoundedRect(graphics, face, radius, faceFill);
    Pen outline(edgeColor, (hovered || selected || pressed) ? 1.0f * S : 0.75f * S);
    DrawRoundedOutline(graphics, face, radius, outline);
    if (!pressed && (hovered || selected)) {
        Pen sheen(MakeColor(Alpha(selected ? 72.0f : (46.0f + 18.0f * pulse), opacity), 255, 230, 177), 0.8f * S);
        const float inset = radius * 0.62f;
        graphics.DrawLine(&sheen, face.X + inset, face.Y + 1.0f * S,
                          face.GetRight() - inset, face.Y + 1.0f * S);
    }
}

void Tick(HWND hwnd);

RectF GetLeftPageArrowRect() {
    const float islandLeft = kCanvasWidth / 2.0f - g_width / 2.0f;
    // Match the reference artwork's arrow locations. Both positions are measured
    // from the same artboard, so they remain symmetric when the island is resized.
    const float centerX = islandLeft + MusicReferenceX(63.0f);
    const float centerY = g_dropY + MusicReferenceY(329.0f);
    const float w = MusicReferenceDeltaX(38.0f);
    const float h = MusicReferenceDeltaY(52.0f);
    return RectF(centerX - w / 2.0f, centerY - h / 2.0f, w, h);
}

RectF GetRightPageArrowRect() {
    const float islandLeft = kCanvasWidth / 2.0f - g_width / 2.0f;
    const float centerX = islandLeft + MusicReferenceX(1992.0f);
    const float centerY = g_dropY + MusicReferenceY(329.0f);
    const float w = MusicReferenceDeltaX(38.0f);
    const float h = MusicReferenceDeltaY(52.0f);
    return RectF(centerX - w / 2.0f, centerY - h / 2.0f, w, h);
}

RectF GetMusicProgressRect() {
    const float S = kUiScale;
    const float cardLeft = kCanvasWidth / 2.0f - g_width / 2.0f;
    const float trackX = MusicTrackXOffset();
    const float trackY = g_dropY + MusicTrackYOffset();
    const float trackWidth = MusicTrackWidth();
    // Hit target exactly matches the visible track's horizontal extent and follows its animation.
    return RectF(cardLeft + trackX, trackY - 8.0f * S, trackWidth, 16.0f * S);
}

float ProgressRatioAt(float mouseX) {
    const RectF rect = GetMusicProgressRect();
    const float ratio = (mouseX - rect.X) / rect.Width;
    return (std::min)(1.0f, (std::max)(0.0f, ratio));
}

RectF GetMusicLyricsRect() {
    const float cardLeft = kCanvasWidth / 2.0f - g_width / 2.0f;
    const float lyricsT = Clamp01(g_lyricsT);
    const float controlsY = g_dropY + MusicControlsYOffset();
    const float half = MusicReferenceDeltaY(60.0f) * (1.0f - 0.30f * lyricsT);
    return RectF(cardLeft + MusicCenter(3) - half, controlsY - half, half * 2.0f, half * 2.0f);
}

RectF GetMusicControlRect(int index) {
    const float cardLeft = kCanvasWidth / 2.0f - g_width / 2.0f;
    const float lyricsT = Clamp01(g_lyricsT);
    const float controlsY = g_dropY + MusicControlsYOffset();
    const float baseHalf = index == 1 ? MusicReferenceDeltaY(86.0f) : MusicReferenceDeltaY(60.0f);
    const float half = baseHalf * (1.0f - 0.30f * lyricsT);
    return RectF(cardLeft + MusicCenter(index) - half,
                 controlsY - half, half * 2.0f, half * 2.0f);
}

// Page dots: same geometry as DrawCenteredPageIndicator, so the clickable areas match the drawing.
RectF GetPageIndicatorRect(int index) {
    const float S = kUiScale;
    const float cx = kCanvasWidth / 2.0f;
    const float y = g_dropY + 131.0f * S;
    const float slotStep = 12.0f * S;
    const float activeWidth = 14.0f * S;
    const float groupWidth = activeWidth + static_cast<float>(kIslandPageCount - 1) * slotStep;
    const float startX = cx - groupWidth / 2.0f;
    return RectF(startX + index * slotStep, y - 5.0f * S, slotStep, 12.5f * S);
}

int IslandPageIdFromOrder(int orderIndex) {
    const int safeIndex = std::clamp(orderIndex, 0, kIslandPageCount - 1);
    return kIslandPageOrder[static_cast<size_t>(safeIndex)];
}

int IslandPageOrderFromId(int pageId) {
    for (int i = 0; i < kIslandPageCount; ++i) {
        if (kIslandPageOrder[static_cast<size_t>(i)] == pageId) return i;
    }
    return 0;
}

// Jump to a page by its visual navigation position, with the same animated slide the arrows use.
void GoToIslandPage(HWND hwnd, int targetOrder) {
    if (targetOrder < 0 || targetOrder >= kIslandPageCount) return;
    const int currentOrder = IslandPageOrderFromId(g_currentIslandPage);
    const int targetPage = IslandPageIdFromOrder(targetOrder);
    if (targetPage == g_currentIslandPage) return;
    g_previousIslandPage = g_currentIslandPage;
    g_pageSlideDirection = targetOrder > currentOrder ? 1 : -1;
    g_currentIslandPage = targetPage;
    g_pageTransitionStart = GetTickCount64();
    g_pageTransitioning = g_visualEffectsEnabled && g_effectPageTransitionStyle != 2;
    g_firstFrame = true;
    Tick(hwnd);
}

void ChangeIslandPage(HWND hwnd, int direction) {
    if (direction != -1 && direction != 1) return;
    const int currentOrder = IslandPageOrderFromId(g_currentIslandPage);
    const int nextOrder = (currentOrder + direction + kIslandPageCount) % kIslandPageCount;
    g_previousIslandPage = g_currentIslandPage;
    g_currentIslandPage = IslandPageIdFromOrder(nextOrder);
    g_pageSlideDirection = direction;
    g_pageTransitionStart = GetTickCount64();
    g_pageTransitioning = g_visualEffectsEnabled && g_effectPageTransitionStyle != 2;
    g_firstFrame = true;
    Tick(hwnd);
}

ULONGLONG GetPageTransitionDurationMs() {
    const float speed = (std::max)(0.50f, g_islandAnimationSpeed);
    const float configured = static_cast<float>(std::clamp(g_effectPageTransitionDurationMs, 150, 1000));
    return static_cast<ULONGLONG>(std::round(configured / speed));
}

float GetPageTransitionProgress(ULONGLONG now) {
    if (!g_visualEffectsEnabled || !g_pageTransitioning) return 1.0f;
    const float duration = static_cast<float>(GetPageTransitionDurationMs());
    const float linear = Clamp01(static_cast<float>(now - g_pageTransitionStart) / duration);
    // All styles use a soft ease; only the painter changes whether pages slide or fade.
    return linear * linear * (3.0f - 2.0f * linear);
}

RectF GetSettingsCategoryRect(int index) {
    const RectF panel = GetSettingsPanelRect();
    const float centerY = panel.Y + (63.0f + index * 33.0f) * kUiScale;
    return RectF(panel.X + 12.0f * kUiScale, centerY - 14.0f * kUiScale,
                 132.0f * kUiScale, 29.0f * kUiScale);
}

int SettingsCategoryAt(float x, float y) {
    for (int i = 0; i < 9; ++i) {
        if (PointInRect(x, y, GetSettingsCategoryRect(i))) return i;
    }
    return -1;
}

// A 3x3 picker matches the nine eye concepts in the reference sheet.
RectF GetEyeThemeGalleryImageRect() {
    const RectF panel = GetSettingsPanelRect();
    const float S = kUiScale;
    const float contentX = panel.X + 154.0f * S;
    const float contentWidth = panel.Width - 154.0f * S;
    const float inset = 8.0f * S;
    const float aspect = 1532.0f / 657.0f;
    float width = (std::max)(1.0f, contentWidth - 2.0f * inset);
    float height = width / aspect;
    const float yOffset = 79.5f * S;
    const float maxHeight = (std::max)(1.0f, panel.Height - yOffset - 8.0f * S);
    if (height > maxHeight) {
        height = maxHeight;
        width = height * aspect;
    }
    const float x = contentX + (contentWidth - width) * 0.5f;
    const float y = panel.Y + yOffset;
    return RectF(x, y, width, height);
}

RectF GetEyeThemeTileRect(int index) {
    if (index < 0 || index >= 9) return RectF();
    EnsureEyeThemeGalleryBitmapLoaded();
    if (g_eyeThemeGalleryBitmap) {
        const RectF image = GetEyeThemeGalleryImageRect();
        // Independent normalized bounds measured from each rounded card in the embedded
        // 1532 x 657 reference sheet. Keeping all nine rectangles explicit prevents the
        // selected outline and hit target from drifting into neighbouring cards.
        static constexpr float lefts[9] = {
            14.0f/1532.0f, 522.0f/1532.0f, 1029.0f/1532.0f,
            14.0f/1532.0f, 522.0f/1532.0f, 1029.0f/1532.0f,
            14.0f/1532.0f, 522.0f/1532.0f, 1029.0f/1532.0f
        };
        static constexpr float rights[9] = {
            506.0f/1532.0f, 1015.0f/1532.0f, 1521.0f/1532.0f,
            506.0f/1532.0f, 1015.0f/1532.0f, 1521.0f/1532.0f,
            506.0f/1532.0f, 1015.0f/1532.0f, 1521.0f/1532.0f
        };
        static constexpr float tops[9] = {
            6.0f/657.0f, 6.0f/657.0f, 6.0f/657.0f,
            223.0f/657.0f, 223.0f/657.0f, 223.0f/657.0f,
            440.0f/657.0f, 440.0f/657.0f, 440.0f/657.0f
        };
        static constexpr float bottoms[9] = {
            207.0f/657.0f, 207.0f/657.0f, 207.0f/657.0f,
            425.0f/657.0f, 425.0f/657.0f, 425.0f/657.0f,
            642.0f/657.0f, 642.0f/657.0f, 642.0f/657.0f
        };
        return RectF(image.X + image.Width * lefts[index], image.Y + image.Height * tops[index],
                     image.Width * (rights[index] - lefts[index]),
                     image.Height * (bottoms[index] - tops[index]));
    }
    // If the embedded sheet cannot be decoded, fall back to the fully interactive native grid.
    const RectF panel = GetSettingsPanelRect();
    const float S = kUiScale;
    const float x = panel.X + 164.0f * S;
    const float y = panel.Y + 81.0f * S;
    const float width = (panel.Width - 154.0f * S - 30.0f * S);
    const float gapX = 7.0f * S;
    const float gapY = 7.0f * S;
    const float tileW = (width - 2.0f * gapX) / 3.0f;
    const float tileH = 89.0f * S;
    const int col = index % 3;
    const int row = index / 3;
    return RectF(x + col * (tileW + gapX), y + row * (tileH + gapY), tileW, tileH);
}

// Two-column, five-row language gallery, sized to remain inside the existing settings panel.
RectF GetLanguageCardRect(int index) {
    if (index < 0 || index >= 10) return RectF();
    const RectF panel = GetSettingsPanelRect();
    const float S = kUiScale;
    const int column = index % 2;
    const int row = index / 2;
    constexpr float left = 172.0f;
    constexpr float cardWidth = 274.0f;
    constexpr float gapX = 12.0f;
    constexpr float top = 82.0f;
    constexpr float rowStep = 57.0f;
    constexpr float cardHeight = 49.0f;
    return RectF(panel.X + (left + column * (cardWidth + gapX)) * S,
                 panel.Y + (top + row * rowStep) * S,
                 cardWidth * S, cardHeight * S);
}

// Three equal-width tabs form the View page navigation.
RectF GetViewSubmenuRect(int index) {
    if (index < 0 || index >= 3) return RectF();
    const RectF panel = GetSettingsPanelRect();
    const float S = kUiScale;
    constexpr float contentX = 154.0f;
    constexpr float contentWidth = 596.0f;
    constexpr float barInset = 12.0f;
    constexpr float innerInset = 4.0f;
    constexpr float gap = 3.0f;
    const float barWidth = (contentWidth - 2.0f * barInset) * S;
    const float tabWidth = (barWidth - 2.0f * innerInset * S - 2.0f * gap * S) / 3.0f;
    const float x = panel.X + (contentX + barInset) * S + innerInset * S +
                    index * (tabWidth + gap * S);
    return RectF(x, panel.Y + (54.0f + 10.0f) * S,
                 tabWidth, 29.0f * S);
}

// Göz is a dedicated settings category; the existing Görünüm submenus remain intact.
void DrawGeneralButton(Graphics& graphics, const RectF& rect, const std::wstring& label,
                       float opacity);

// Dinamik Ada submenu controls. All coordinates are relative to the existing settings panel.
RectF GetIslandSettingsSliderTrackRect(int index) {
    const RectF panel = GetSettingsPanelRect();
    constexpr float yOffsets[] = {96.0f, 140.0f, 162.0f, 184.0f, 226.0f, 310.0f, 118.0f};
    if (index < 0 || index >= 7) return RectF();
    return RectF(panel.X + (154.0f + 270.0f) * kUiScale,
                 panel.Y + (54.0f + yOffsets[index]) * kUiScale,
                 145.0f * kUiScale, 1.0f);
}

RectF GetIslandSettingsSliderHitRect(int index) {
    const RectF track = GetIslandSettingsSliderTrackRect(index);
    const float pad = 10.0f * kUiScale;
    return RectF(track.X - pad, track.Y - 12.0f * kUiScale,
                 track.Width + pad * 2.0f, 24.0f * kUiScale);
}

RectF GetIslandContentToggleRect(int index) {
    const RectF panel = GetSettingsPanelRect();
    constexpr float yOffsets[] = {262.0f, 286.0f};
    if (index < 0 || index >= 2) return RectF();
    return RectF(panel.X + (154.0f + 550.0f) * kUiScale,
                 panel.Y + (54.0f + yOffsets[index] - 8.0f) * kUiScale,
                 30.0f * kUiScale, 18.0f * kUiScale);
}

float IslandSettingsSliderNormalized(int index) {
    switch (index) {
        case 0: return Clamp01((g_islandSizeScale - 0.70f) / 0.90f);
        case 1: return Clamp01((g_islandExpandedWidthScale - 0.85f) / 0.50f);
        case 2: return Clamp01((g_islandExpandedHeightScale - 0.95f) / 0.35f);
        case 3: return Clamp01((g_islandCornerScale - 0.30f) / 1.20f);
        case 4: return Clamp01((g_islandAnimationSpeed - 0.50f) / 1.50f);
        case 5: return Clamp01(g_pageArrowInset / 18.0f);
        case 6: return Clamp01((g_eyeSizeScale - 0.70f) / 0.90f);
        default: return 0.0f;
    }
}

void DrawIslandSettingsSlider(Graphics& graphics, int index, const std::wstring& label,
                              const std::wstring& valueText, float opacity) {
    const RectF panel = GetSettingsPanelRect();
    const RectF track = GetIslandSettingsSliderTrackRect(index);
    const float S = kUiScale;
    constexpr float labelY[] = {86.0f, 130.0f, 152.0f, 174.0f, 216.0f, 300.0f, 108.0f};
    DrawLabel(graphics, label, panel.X + (154.0f + 26.0f) * S,
              panel.Y + (54.0f + labelY[index]) * S,
              8.7f, MakeColor(Alpha(245.0f, opacity), 247, 241, 226), true);

    Pen base(MakeColor(Alpha(115.0f, opacity), 130, 133, 148), 3.4f * S);
    base.SetStartCap(LineCapRound);
    base.SetEndCap(LineCapRound);
    graphics.DrawLine(&base, track.X, track.Y, track.GetRight(), track.Y);
    const float progress = IslandSettingsSliderNormalized(index);
    Pen glow(MakeColor(Alpha(42.0f, opacity), 239, 185, 86), 7.0f * S);
    glow.SetStartCap(LineCapRound); glow.SetEndCap(LineCapRound);
    graphics.DrawLine(&glow, track.X, track.Y, track.X + track.Width * progress, track.Y);
    Pen active(MakeColor(Alpha(248.0f, opacity), 242, 196, 105), 3.4f * S);
    active.SetStartCap(LineCapRound);
    active.SetEndCap(LineCapRound);
    graphics.DrawLine(&active, track.X, track.Y, track.X + track.Width * progress, track.Y);
    SolidBrush thumb(MakeColor(Alpha(255.0f, opacity), 255, 224, 157));
    graphics.FillEllipse(&thumb, track.X + track.Width * progress - 5.0f * S,
                         track.Y - 5.0f * S, 10.0f * S, 10.0f * S);
    DrawCenteredText(graphics, valueText, track.GetRight() + 30.0f * S,
                     track.Y - 5.0f * S, 7.8f,
                     MakeColor(Alpha(248.0f, opacity), 246, 224, 176), true);
}

