void DrawDynamicIslandSettings(Graphics& graphics, const RectF& content, float opacity) {
    const float S = kUiScale;
    DrawSettingsCard(graphics, RectF(content.X + 10.0f*S, content.Y + 108.0f*S,
                                     content.Width - 20.0f*S, content.Height - 118.0f*S), opacity);
    const Color primary = MakeColor(Alpha(246.0f, opacity), 247, 244, 236);
    const Color secondary = MakeColor(Alpha(220.0f, opacity), 215, 204, 183);
    auto section = [&](const wchar_t* title, float y) {
        DrawLabel(graphics, title, content.X + 25.0f * S, content.Y + (54.0f + y) * S,
                  10.0f, primary, true);
    };
    section(L"Boyut ve Şekil", 67.0f);
    DrawIslandSettingsSlider(graphics, 0, L"Bekleme görünümü boyutu",
        std::to_wstring(static_cast<int>(std::round(g_islandSizeScale * 100.0f))) + L"%", opacity);
    DrawIslandSettingsSlider(graphics, 6, L"Göz boyutu",
        std::to_wstring(static_cast<int>(std::round(g_eyeSizeScale * 100.0f))) + L"%", opacity);
    DrawIslandSettingsSlider(graphics, 1, L"Ada genişliği",
        std::to_wstring(static_cast<int>(std::round(g_islandExpandedWidthScale * 100.0f))) + L"%", opacity);
    DrawIslandSettingsSlider(graphics, 2, L"Ada yüksekliği",
        std::to_wstring(static_cast<int>(std::round(g_islandExpandedHeightScale * 100.0f))) + L"%", opacity);
    DrawIslandSettingsSlider(graphics, 3, L"Köşe yuvarlaklığı",
        std::to_wstring(static_cast<int>(std::round(g_islandCornerScale * 100.0f))) + L"%", opacity);

    section(L"Animasyon", 202.0f);
    DrawIslandSettingsSlider(graphics, 4, L"Açılma ve kapanma hızı",
        std::to_wstring(static_cast<int>(std::round(g_islandAnimationSpeed * 100.0f))) + L"%", opacity);

    section(L"İçerik Yerleşimi", 240.0f);
    DrawLabel(graphics, L"Sayfa göstergelerini göster", content.X + 26.0f * S,
              content.Y + (54.0f + 262.0f) * S, 8.8f, secondary, false);
    DrawToggleSwitch(graphics, GetIslandContentToggleRect(0), g_showPageIndicator, opacity);
    DrawLabel(graphics, L"Sayfa gezinme oklarını göster", content.X + 26.0f * S,
              content.Y + (54.0f + 286.0f) * S, 8.8f, secondary, false);
    DrawToggleSwitch(graphics, GetIslandContentToggleRect(1), g_showPageArrows, opacity);
    DrawIslandSettingsSlider(graphics, 5, L"Okların içeri kayması",
        std::to_wstring(static_cast<int>(std::round(g_pageArrowInset))) + L" px", opacity);
}


float GetGeneralRowCenterY(int row) {
    const RectF panel = GetSettingsPanelRect();
    const float contentY = panel.Y + 54.0f * kUiScale;
    const int maxScroll = (std::max)(0, kGeneralSettingsRowCount - kGeneralSettingsVisibleRows);
    const int scroll = std::clamp(g_generalScrollOffset, 0, maxScroll);

    // Keep the row and hit-test position identical, while leaving a larger gap
    // between the three HTML-style cards (rows 0-2, 3-6, and 7-12).
    int cardGapCount = 0;
    constexpr int cardStarts[] = {3, 7};
    if (row > scroll) {
        for (int boundary : cardStarts) {
            if (boundary > scroll && boundary <= row) ++cardGapCount;
        }
    } else if (row < scroll) {
        for (int boundary : cardStarts) {
            if (boundary > row && boundary <= scroll) --cardGapCount;
        }
    }
    const float slot = 89.0f + static_cast<float>(row - scroll) * 30.0f +
                       static_cast<float>(cardGapCount) * 34.0f;
    return contentY + slot * kUiScale;
}

