float GetMusicSettingRowCenterY(int row) {
    // DrawMusicSettings receives a content rectangle whose origin is the panel top.
    // GetSettingsContentRect() starts 54 scaled units lower, so using its Y here
    // displaced every row from its card by exactly that amount. Keep the row and
    // card coordinate origins identical; the same helper is also used for hit tests.
    const RectF panel = GetSettingsPanelRect();
    constexpr float offsets[] = {120.0f, 148.0f, 176.0f, 262.0f, 297.0f,
                                 0.0f, 0.0f, 386.0f, 416.0f, 446.0f};
    if (row < 0 || row >= 10) return panel.Y;
    const float scroll = static_cast<float>(g_musicScrollOffset) * 28.0f * kUiScale;
    return panel.Y + offsets[row] * kUiScale - scroll;
}

