int GetEffectsVisualSlot(int row) {
    if (row < 0 || row >= kEffectsSettingsRowCount) return 0;
    return row;
}

constexpr float kEffectsSlotHeight = 31.0f;

float EffectsScrollOffsetY(int scroll) {
    return static_cast<float>(scroll) * kEffectsSlotHeight;
}

float EffectsVisualSlotY(int slot, int scroll) {
    // Three visually separate cards: the existing RGB strip, music-wave controls,
    // and the remaining visual effects. The larger gaps mark card boundaries.
    static constexpr float kRowY[kEffectsSettingsRowCount] = {140.0f, 184.0f, 215.0f, 259.0f, 290.0f, 321.0f, 352.0f};
    const int safeSlot = std::clamp(slot, 0, kEffectsSettingsRowCount - 1);
    return kRowY[safeSlot] - EffectsScrollOffsetY(scroll);
}

float GetEffectsRowCenterY(int row) {
    const RectF panel = GetSettingsPanelRect();
    const int maxScroll = (std::max)(0, kEffectsSettingsVisualSlotCount - kEffectsSettingsVisibleRows);
    const int scroll = std::clamp(g_effectsScrollOffset, 0, maxScroll);
    return panel.Y + EffectsVisualSlotY(GetEffectsVisualSlot(row), scroll) * kUiScale;
}

