void DrawToggleSwitch(Graphics& graphics, const RectF& rect, bool enabled, float opacity) {
    if (rect.Width <= 0.0f || rect.Height <= 0.0f || opacity <= 0.01f) return;
    const float S = kUiScale;
    const bool hovered = IsCursorOverUiRect(rect);
    const bool pressed = hovered && GetCapture() == LoadIslandWindowHandle() && g_pressedControl != 0;
    const ULONGLONG now = GetTickCount64();
    const float pulsePhase = static_cast<float>(now % 1900ULL) / 1900.0f;
    const float pulse = 0.5f + 0.5f * std::sin(pulsePhase * 2.0f * kPi);

    // MorphState preserves the existing boolean control. Only its native drawing changes.
    struct MorphState {
        bool initialized = false;
        bool targetOn = false;
        float position = 0.0f;
        float from = 0.0f;
        ULONGLONG start = 0;
    };
    static std::map<std::uint64_t, MorphState> morphStates;
    const auto qx = static_cast<std::int32_t>(std::lround(rect.X * 4.0f));
    const auto qy = static_cast<std::int32_t>(std::lround(rect.Y * 4.0f));
    const std::uint64_t key = (static_cast<std::uint64_t>(static_cast<std::uint32_t>(qx)) << 32) |
                              static_cast<std::uint32_t>(qy);
    MorphState& morph = morphStates[key];
    const float target = enabled ? 1.0f : 0.0f;
    if (!morph.initialized) {
        morph.initialized = true;
        morph.targetOn = enabled;
        morph.position = target;
        morph.from = target;
        morph.start = now;
    } else if (morph.targetOn != enabled) {
        morph.targetOn = enabled;
        morph.from = morph.position;
        morph.start = now;
    }
    const float transition = static_cast<float>(now - morph.start) / 240.0f;
    const float t = Clamp01(transition);
    const float eased = t * t * (3.0f - 2.0f * t);
    morph.position = morph.from + (target - morph.from) * eased;
    const float stretch = transition < 1.0f ? std::sin(t * kPi) : 0.0f;

    const float radius = rect.Height * 0.5f;
    const RectF trackRect(rect.X, rect.Y, rect.Width, rect.Height);
    const RectF haloRect(rect.X - 0.65f * S, rect.Y - 0.65f * S,
                         rect.Width + 1.3f * S, rect.Height + 1.3f * S);
    SolidBrush trackFill(MakeColor(Alpha(248.0f, opacity), 8, 8, 7));
    DrawRoundedRect(graphics, trackRect, radius, trackFill);

    const float outerStrength = enabled ? (10.0f + 6.0f * pulse) : (hovered ? 5.0f : 1.0f);
    Pen outerGlow(MakeColor(Alpha(outerStrength, opacity), 235, 185, 92), 3.5f * S);
    outerGlow.SetLineJoin(LineJoinRound);
    DrawRoundedOutline(graphics, haloRect, radius + 0.65f * S, outerGlow);

    const BYTE edgeAlpha = static_cast<BYTE>(std::clamp(
        (enabled ? 218.0f + 24.0f * pulse : (hovered ? 165.0f : 90.0f)) * opacity,
        0.0f, 255.0f));
    Pen edge(Color(edgeAlpha, enabled ? 226 : 133, enabled ? 177 : 103, enabled ? 83 : 54),
             (enabled ? 1.0f : 0.8f) * S);
    edge.SetLineJoin(LineJoinRound);
    DrawRoundedOutline(graphics, trackRect, radius, edge);

    const float inset = (std::max)(1.0f * S, rect.Height * 0.10f);
    const float knobRadius = (rect.Height - inset * 2.0f) * 0.5f;
    const float leftCx = rect.X + inset + knobRadius;
    const float rightCx = rect.GetRight() - inset - knobRadius;
    const float cx = leftCx + (rightCx - leftCx) * morph.position;
    const float cy = rect.Y + rect.Height * 0.5f;
    const float diskRadius = knobRadius * (0.91f - 0.035f * stretch) * (pressed ? 0.96f : 1.0f);

    // A visible circular ember and progress arc adapt the CodeFronts Timed Toggle
    // motif to this compact switch without changing the original hit target or layout.
    if (enabled || hovered || stretch > 0.02f) {
        const float haloRadius = diskRadius * (1.45f + 0.06f * pulse);
        SolidBrush knobHalo(Color(static_cast<BYTE>(std::clamp(
            ((enabled ? 13.0f + 8.0f * pulse : 5.0f + 7.0f * stretch) * opacity), 0.0f, 255.0f)),
            238, 180, 77));
        graphics.FillEllipse(&knobHalo, cx - haloRadius, cy - haloRadius,
                             haloRadius * 2.0f, haloRadius * 2.0f);
    }

    SolidBrush knobFace(MakeColor(Alpha(252.0f, opacity), enabled ? 27 : 20,
                                  enabled ? 20 : 19, enabled ? 10 : 17));
    graphics.FillEllipse(&knobFace, cx - diskRadius, cy - diskRadius,
                         diskRadius * 2.0f, diskRadius * 2.0f);
    Pen knobEdge(MakeColor(Alpha(enabled ? 236.0f : 122.0f, opacity),
                           enabled ? 242 : 142, enabled ? 195 : 119, enabled ? 105 : 72),
                 0.75f * S);
    graphics.DrawEllipse(&knobEdge, cx - diskRadius, cy - diskRadius,
                         diskRadius * 2.0f, diskRadius * 2.0f);

    const float arcRadius = diskRadius * 0.78f;
    const RectF arcBounds(cx - arcRadius, cy - arcRadius, arcRadius * 2.0f, arcRadius * 2.0f);
    Pen arcTrack(Color(Alpha(118.0f, opacity), 104, 77, 39), 1.35f * S);
    arcTrack.SetLineJoin(LineJoinRound);
    graphics.DrawArc(&arcTrack, arcBounds, -90.0f, 360.0f);

    const float arcProgress = enabled
        ? Clamp01(static_cast<float>(now - morph.start) / 680.0f)
        : 0.0f;
    if (arcProgress > 0.001f) {
        const float sweep = 312.0f * arcProgress;
        Pen arcHalo(Color(static_cast<BYTE>(std::clamp((36.0f + 12.0f * pulse) * opacity, 0.0f, 255.0f)),
                          250, 194, 96), 3.3f * S);
        arcHalo.SetStartCap(LineCapRound);
        arcHalo.SetEndCap(LineCapRound);
        graphics.DrawArc(&arcHalo, arcBounds, -90.0f, sweep);
        Pen arcCore(Color(static_cast<BYTE>(std::clamp((enabled ? 245.0f : 0.0f) * opacity, 0.0f, 255.0f)),
                          245, 194, 105), 1.45f * S);
        arcCore.SetStartCap(LineCapRound);
        arcCore.SetEndCap(LineCapRound);
        graphics.DrawArc(&arcCore, arcBounds, -90.0f, sweep);
    }

    const float dotRadius = (std::max)(1.1f * S, diskRadius * 0.24f);
    if (enabled) {
        SolidBrush dotGlow(Color(static_cast<BYTE>(std::clamp((25.0f + 12.0f * pulse) * opacity, 0.0f, 255.0f)),
                                 255, 215, 130));
        graphics.FillEllipse(&dotGlow, cx - dotRadius * 2.0f, cy - dotRadius * 2.0f,
                             dotRadius * 4.0f, dotRadius * 4.0f);
    }
    SolidBrush centerDot(MakeColor(Alpha(enabled ? 255.0f : 115.0f, opacity),
                                    enabled ? 255 : 135, enabled ? 213 : 123, enabled ? 123 : 73));
    graphics.FillEllipse(&centerDot, cx - dotRadius, cy - dotRadius,
                         dotRadius * 2.0f, dotRadius * 2.0f);
}


void DrawGeneralButton(Graphics& graphics, const RectF& rect, const std::wstring& label,
                       float opacity) {
    const bool hovered = IsCursorOverUiRect(rect);
    const bool pressed = hovered && GetCapture() == LoadIslandWindowHandle() && g_pressedControl != 0;
    const bool profileButton = (label == L"Günlük" || label == L"Sade");
    const ULONGLONG now = GetTickCount64();
    const float pulse = 0.5f + 0.5f * std::sin(static_cast<float>(now % 1600ULL) * (2.0f * kPi / 1600.0f));
    // Keep the profile control subtly accented; the full neon pulse is hover-only.
    DrawModernButtonSurface(graphics, rect, opacity, false, hovered || profileButton, pressed);
    if (g_visualEffectsEnabled && hovered) {
        const float strength = 0.55f + 0.45f * pulse;
        const float pad = (2.0f + 1.0f * pulse) * kUiScale;
        RectF outer(rect.X - pad, rect.Y - pad, rect.Width + 2.0f * pad, rect.Height + 2.0f * pad);
        SolidBrush soft(MakeColor(Alpha((7.0f + 5.0f * pulse) * strength, opacity), 236, 188, 91));
        DrawRoundedRect(graphics, outer, 9.0f * kUiScale, soft);
        Pen neon(MakeColor(Alpha((155.0f + 45.0f * pulse) * strength, opacity), 244, 199, 111),
                 (0.9f + 0.25f * pulse) * kUiScale);
        DrawRoundedOutline(graphics, rect, 8.0f * kUiScale, neon);
    }
    // Text remains clean and readable; only the button surface glows.
    DrawCenteredText(graphics, label, rect.X + rect.Width / 2.0f,
                     rect.Y + rect.Height / 2.0f - 4.0f * kUiScale + (pressed ? 0.4f * kUiScale : 0.0f),
                     7.2f, MakeColor(Alpha(250.0f, opacity), 248, 247, 241), true);
}


