void UpdateEyeColorPickerFromPoint(HWND hwnd, float mouseX, float mouseY, int mode) {
    if (mode == 1) {
        const RectF wheel = GetEyePickerWheelRect();
        const float cx = wheel.X + wheel.Width * 0.5f;
        const float cy = wheel.Y + wheel.Height * 0.5f;
        // Hue zero is at the top of the wheel, matching the rendered ring.
        g_eyePickerHue = std::atan2(mouseY - cy, mouseX - cx) * 180.0f / kPi + 90.0f;
        if (g_eyePickerHue < 0.0f) g_eyePickerHue += 360.0f;
        if (g_eyePickerHue >= 360.0f) g_eyePickerHue -= 360.0f;
    } else if (mode == 2) {
        const RectF disc = GetEyePickerValueRect();
        const float cx = disc.X + disc.Width * 0.5f;
        const float cy = disc.Y + disc.Height * 0.5f;
        const float radius = disc.Width * 0.5f;
        float dx = (mouseX - cx) / radius;
        float dy = (mouseY - cy) / radius;
        const float distance = std::sqrt(dx * dx + dy * dy);
        if (distance > 1.0f && distance > 0.0f) { dx /= distance; dy /= distance; }
        dy = std::clamp(dy, -1.0f, 1.0f);
        const float chord = std::sqrt((std::max)(0.0f, 1.0f - dy * dy));
        g_eyePickerSaturation = chord > 0.001f
            ? std::clamp((dx / chord + 1.0f) * 0.5f, 0.0f, 1.0f)
            : g_eyePickerSaturation;
        g_eyePickerValue = std::clamp((1.0f - dy) * 0.5f, 0.0f, 1.0f);
    } else {
        return;
    }
    g_customEyeColor = EyePickerHsvToColor(g_eyePickerHue, g_eyePickerSaturation, g_eyePickerValue);
    g_eyeColorIndex = 3;
    g_firstFrame = true;
    Tick(hwnd);
}









