std::vector<uint8_t> DecodeMusicSilkWaveBase64() {
    std::vector<uint8_t> output;
    output.reserve(650000);
    uint32_t accumulator = 0;
    int bits = -8;
    for (const char* chunk : kMusicSilkWaveBase64Chunks) {
        for (const unsigned char* p = reinterpret_cast<const unsigned char*>(chunk); *p; ++p) {
            const unsigned char c = *p;
            if (c == '=') continue;
            int value = -1;
            if (c >= 'A' && c <= 'Z') value = c - 'A';
            else if (c >= 'a' && c <= 'z') value = c - 'a' + 26;
            else if (c >= '0' && c <= '9') value = c - '0' + 52;
            else if (c == '+') value = 62;
            else if (c == '/') value = 63;
            if (value < 0) continue;
            accumulator = (accumulator << 6) | static_cast<uint32_t>(value);
            bits += 6;
            if (bits >= 0) {
                output.push_back(static_cast<uint8_t>((accumulator >> bits) & 0xFFu));
                bits -= 8;
            }
        }
    }
    return output;
}

std::unique_ptr<Bitmap> LoadMusicSilkWaveBitmap() {
    const std::vector<uint8_t> bytes = DecodeMusicSilkWaveBase64();
    if (bytes.empty()) return nullptr;
    HGLOBAL memory = GlobalAlloc(GMEM_MOVEABLE, bytes.size());
    if (!memory) return nullptr;
    void* locked = GlobalLock(memory);
    if (!locked) {
        GlobalFree(memory);
        return nullptr;
    }
    std::memcpy(locked, bytes.data(), bytes.size());
    GlobalUnlock(memory);
    IStream* stream = nullptr;
    if (FAILED(CreateStreamOnHGlobal(memory, TRUE, &stream)) || !stream) {
        GlobalFree(memory);
        return nullptr;
    }
    std::unique_ptr<Bitmap> bitmap;
    try {
        bitmap = std::make_unique<Bitmap>(stream);
    } catch (...) {
        stream->Release();
        return nullptr;
    }
    if (!bitmap) {
        stream->Release();
        return nullptr;
    }
    if (bitmap->GetLastStatus() != Ok) {
        bitmap.reset();
        stream->Release();
        return nullptr;
    }
    g_musicSilkWaveFrameCount = 1;
    g_musicSilkWaveActiveFrame = std::numeric_limits<UINT>::max();
    const UINT frameDimensionCount = bitmap->GetFrameDimensionsCount();
    if (frameDimensionCount > 0) {
        std::vector<GUID> dimensions(frameDimensionCount);
        if (bitmap->GetFrameDimensionsList(dimensions.data(), frameDimensionCount) == Ok) {
            for (const GUID& dimension : dimensions) {
                if (std::memcmp(&dimension, &kMusicSilkWaveTimeDimension, sizeof(GUID)) == 0) {
                    const UINT frameCount = bitmap->GetFrameCount(&dimension);
                    if (frameCount > 1) {
                        g_musicSilkWaveFrameCount = frameCount;
                    }
                    break;
                }
            }
        }
    }
    // Per GDI+ documentation, the source IStream must stay alive for the Bitmap's
    // entire lifetime. Retain it and release it only after resetting the bitmap.
    g_musicSilkWaveStream = stream;
    return bitmap;
}

void ReleaseMusicSilkWaveBitmap() {
    g_musicSilkWave.reset();
    if (g_musicSilkWaveStream) {
        g_musicSilkWaveStream->Release();
        g_musicSilkWaveStream = nullptr;
    }
}

