void EnsureEyeThemeArtCropsLoaded() {
    if (g_eyeThemeArtCropsLoadAttempted) return;
    g_eyeThemeArtCropsLoadAttempted = true;
    EnsureEyeThemeGalleryBitmapLoaded();
    Bitmap* source = g_eyeThemeGalleryBitmap.get();
    if (!source || source->GetLastStatus() != Ok) return;

    // Eye-only windows into the embedded concept sheet. Every theme gets its own crop so
    // the real geometry (round rings, angled lids, sleepy arcs, etc.) is preserved.
    static constexpr int kSourceWidth = 1532;
    static constexpr int kSourceHeight = 657;
    static constexpr int kCropWidth = 230;
    static constexpr int kCanvasHeight = 75;
    static constexpr int kCropLeft[3] = {145, 659, 1159};
    static constexpr int kSourceTop[9] = {75, 75, 75, 283, 280, 283, 513, 522, 509};
    static constexpr int kSourceHeightForTheme[9] = {61, 61, 59, 70, 73, 70, 60, 38, 64};
    static constexpr int kCanvasTop[9] = {7, 7, 8, 2, 1, 2, 7, 16, 5};
    const float scaleX = static_cast<float>(source->GetWidth()) / static_cast<float>(kSourceWidth);
    const float scaleY = static_cast<float>(source->GetHeight()) / static_cast<float>(kSourceHeight);

    for (int theme = 0; theme < 9; ++theme) {
        const int col = theme % 3;
        const int srcX = static_cast<int>(std::round(kCropLeft[col] * scaleX));
        const int srcY = static_cast<int>(std::round(kSourceTop[theme] * scaleY));
        const int cropW = (std::min)(kCropWidth, static_cast<int>(source->GetWidth()) - srcX);
        const int cropH = (std::min)(kSourceHeightForTheme[theme],
                                     static_cast<int>(source->GetHeight()) - srcY);
        if (srcX < 0 || srcY < 0 || cropW < 8 || cropH < 8) continue;

        auto crop = std::make_unique<Bitmap>(kCropWidth, kCanvasHeight, PixelFormat32bppARGB);
        if (!crop || crop->GetLastStatus() != Ok) continue;
        Graphics cropGraphics(crop.get());
        cropGraphics.Clear(Color(0, 0, 0, 0));
        const int destTop = std::clamp(kCanvasTop[theme], 0, kCanvasHeight - cropH);
        for (int py = 0; py < cropH; ++py) {
            for (int px = 0; px < cropW; ++px) {
                Color pixel;
                if (source->GetPixel(srcX + px, srcY + py, &pixel) != Ok) continue;
                const int red = pixel.GetR();
                const int green = pixel.GetG();
                const int blue = pixel.GetB();
                const int maximum = (std::max)({red, green, blue});
                const int minimum = (std::min)({red, green, blue});
                const int saturation = maximum - minimum;
                float alpha = std::clamp((static_cast<float>(maximum) - 40.0f) * 5.0f, 0.0f, 255.0f);
                // Remove the nearly-black field and the low-chroma silk wave behind the eyes.
                // Pale gold/white highlights remain visible because their brightness is high.
                if (maximum < 52) alpha = 0.0f;
                else if (maximum < 86) alpha *= 0.28f;
                if (saturation < 20 && maximum < 220) alpha = 0.0f;
                else if (saturation < 30 && maximum < 245) alpha *= 0.12f;
                crop->SetPixel(px, destTop + py,
                    Color::MakeARGB(static_cast<BYTE>(std::clamp(alpha, 0.0f, 255.0f)),
                                    static_cast<BYTE>(red), static_cast<BYTE>(green),
                                    static_cast<BYTE>(blue)));
            }
        }
        g_eyeThemeArtCrops[static_cast<size_t>(theme)] = std::move(crop);
    }
}

void ReleaseEyeThemeGalleryBitmap() {
    for (auto& crop : g_eyeThemeArtCrops) crop.reset();
    g_eyeThemeArtCropsLoadAttempted = true;
    g_eyeThemeGalleryBitmap.reset();
    if (g_eyeThemeGalleryStream) {
        g_eyeThemeGalleryStream->Release();
        g_eyeThemeGalleryStream = nullptr;
    }
}

