    g_generalUndoSnapshot.startInCompactMode = g_startInCompactMode;
    g_generalUndoSnapshot.autoSaveSettings = g_autoSaveSettings;
    g_generalUndoSnapshot.shortcutModifiers = g_shortcutModifiers;
    g_generalUndoSnapshot.shortcutVirtualKey = g_shortcutVirtualKey;
    g_generalUndoSnapshot.startPageOrder = g_startPageOrder;
