    g_generalUndoSnapshot.hideInFullscreen = g_hideInFullscreen;
    g_generalUndoSnapshot.lowResourceMode = g_lowResourceMode;
    g_generalUndoSnapshot.hideWhenLocked = g_hideWhenLocked;
    g_generalUndoSnapshot.visualEffectsEnabled = g_visualEffectsEnabled;
    g_generalUndoSnapshot.usageProfile = g_usageProfile;
