void ApplyUsageProfile(HWND hwnd) {
    // Profiles intentionally affect only the General-page behavior and broad animation/performance preferences.
    switch (std::clamp(g_usageProfile, 0, 1)) {
        case 0: // Günlük
            g_clickToOpenOnly = true;
            g_startInCompactMode = true;
            g_musicStayEyesMode = false;
            g_hideInFullscreen = false;
            g_lowResourceMode = false;
            g_hideWhenLocked = false;
            g_visualEffectsEnabled = true;
            g_autoExpandMusicOnNewTrack = false;
            break;
        case 1: // Sade
            g_clickToOpenOnly = true;
            g_startInCompactMode = true;
            g_musicStayEyesMode = true;
            g_hideInFullscreen = false;
            g_lowResourceMode = true;
            g_hideWhenLocked = true;
            g_visualEffectsEnabled = false;
            g_autoExpandMusicOnNewTrack = false;
            break;
    }
    SetTimer(hwnd, kAnimationTimer, g_lowResourceMode ? 33 : 16, nullptr);
    g_pageTransitioning = false;
    g_pageIndicatorT = static_cast<float>(IslandPageOrderFromId(g_currentIslandPage));
    g_lastVisibilityPolicyCheck = 0;
    SaveSettingsPreferences();
    g_firstFrame = true;
    Tick(hwnd);
}

void RestoreGeneralUndoSnapshot(HWND hwnd) {
    if (!g_canUndoGeneralSettings) {
        MessageBoxW(hwnd, L"Geri alınabilecek bir Genel ayar değişikliği yok.", L"Merlin", MB_OK | MB_ICONINFORMATION | MB_TOPMOST);
        return;
    }
    const GeneralSettingsSnapshot snapshot = g_generalUndoSnapshot;
    g_clickToOpenOnly = snapshot.clickToOpenOnly;
    g_startInCompactMode = snapshot.startInCompactMode;
    g_autoSaveSettings = snapshot.autoSaveSettings;
    g_shortcutModifiers = snapshot.shortcutModifiers;
    g_shortcutVirtualKey = snapshot.shortcutVirtualKey;
    g_startPageOrder = std::clamp(snapshot.startPageOrder, 0, 3);
    g_musicStayEyesMode = snapshot.musicStayEyesMode;
    g_hideInFullscreen = snapshot.hideInFullscreen;
    g_lowResourceMode = snapshot.lowResourceMode;
    g_hideWhenLocked = snapshot.hideWhenLocked;
    g_visualEffectsEnabled = snapshot.visualEffectsEnabled;
    g_usageProfile = std::clamp(snapshot.usageProfile, 0, 1);
    g_autoExpandMusicOnNewTrack = snapshot.autoExpandMusicOnNewTrack;
    g_canUndoGeneralSettings = false;
    if (!g_visualEffectsEnabled) {
        g_pageTransitioning = false;
        g_topButtonHoverT.fill(0.0f);
        g_topButtonPressT.fill(0.0f);
    }
    SetTimer(hwnd, kAnimationTimer, g_lowResourceMode ? 33 : 16, nullptr);
    g_lastVisibilityPolicyCheck = 0;
    RefreshRegisteredHotkey(hwnd);
    SaveSettingsPreferences(true);
    g_firstFrame = true;
    Tick(hwnd);
}

struct BackupRegistryValue {
    std::wstring name;
    DWORD type = REG_NONE;
    std::vector<BYTE> data;
};

bool WriteExact(HANDLE file, const void* data, DWORD bytes) {
    const BYTE* cursor = static_cast<const BYTE*>(data);
    DWORD remaining = bytes;
    while (remaining > 0) {
        DWORD written = 0;
        if (!WriteFile(file, cursor, remaining, &written, nullptr) || written == 0) return false;
        cursor += written;
        remaining -= written;
    }
    return true;
}

bool ReadExact(HANDLE file, void* data, DWORD bytes) {
    BYTE* cursor = static_cast<BYTE*>(data);
    DWORD remaining = bytes;
    while (remaining > 0) {
        DWORD got = 0;
        if (!ReadFile(file, cursor, remaining, &got, nullptr) || got == 0) return false;
        cursor += got;
        remaining -= got;
    }
    return true;
}

bool ExportSettingsBackup(HWND owner) {
    SaveSettingsPreferences(true);
    wchar_t path[MAX_PATH] = L"Merlin-Ayar-Yedegi.mrb";
    OPENFILENAMEW dialog{};
    dialog.lStructSize = sizeof(dialog);
    dialog.hwndOwner = owner;
    dialog.lpstrFilter = L"Merlin ayar yedeği (*.mrb)\0*.mrb\0Tüm dosyalar (*.*)\0*.*\0\0";
    dialog.lpstrFile = path;
    dialog.nMaxFile = MAX_PATH;
    dialog.lpstrDefExt = L"mrb";
    dialog.Flags = OFN_PATHMUSTEXIST | OFN_OVERWRITEPROMPT | OFN_NOCHANGEDIR;
    if (!GetSaveFileNameW(&dialog)) return false; // Cancel is not an error.

    HKEY key = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, kPreferencesRegistryKey, 0, KEY_QUERY_VALUE, &key) != ERROR_SUCCESS) {
        MessageBoxW(owner, L"Ayar kayıt defteri açılamadı.", L"Yedekleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    DWORD valueCount = 0, maxNameChars = 0, maxDataBytes = 0;
    const LSTATUS queryStatus = RegQueryInfoKeyW(key, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr,
                                                 &valueCount, &maxNameChars, &maxDataBytes, nullptr, nullptr);
    if (queryStatus != ERROR_SUCCESS || valueCount > 256 || maxDataBytes > 1024 * 1024) {
        RegCloseKey(key);
        MessageBoxW(owner, L"Ayar bilgileri okunamadı veya sınırları aşıyor.", L"Yedekleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    std::vector<BackupRegistryValue> values;
    values.reserve(valueCount);
    std::vector<wchar_t> nameBuffer(static_cast<size_t>(maxNameChars) + 2, L'\0');
    std::vector<BYTE> dataBuffer(static_cast<size_t>(maxDataBytes) + 2, 0);
    for (DWORD i = 0; i < valueCount; ++i) {
        DWORD nameChars = static_cast<DWORD>(nameBuffer.size() - 1);
        DWORD type = REG_NONE;
        DWORD dataBytes = static_cast<DWORD>(dataBuffer.size());
        const LSTATUS status = RegEnumValueW(key, i, nameBuffer.data(), &nameChars, nullptr,
                                             &type, dataBuffer.data(), &dataBytes);
        if (status != ERROR_SUCCESS) {
            RegCloseKey(key);
            MessageBoxW(owner, L"Ayarların bir bölümü yedeklenemedi.", L"Yedekleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
            return false;
        }
        BackupRegistryValue value;
        value.name.assign(nameBuffer.data(), nameChars);
        value.type = type;
        value.data.assign(dataBuffer.begin(), dataBuffer.begin() + dataBytes);
        values.push_back(std::move(value));
    }
    RegCloseKey(key);

    HANDLE file = CreateFileW(path, GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS,
                              FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        MessageBoxW(owner, L"Yedek dosyası oluşturulamadı.", L"Yedekleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    static constexpr char magic[8] = {'M','R','L','N','B','K','1','\0'};
    const DWORD formatVersion = 1;
    const DWORD count = static_cast<DWORD>(values.size());
    bool ok = WriteExact(file, magic, sizeof(magic)) &&
              WriteExact(file, &formatVersion, sizeof(formatVersion)) &&
              WriteExact(file, &count, sizeof(count));
    for (const auto& value : values) {
        const DWORD nameChars = static_cast<DWORD>(value.name.size() + 1);
        const DWORD dataBytes = static_cast<DWORD>(value.data.size());
        if (nameChars > 512 || dataBytes > 1024 * 1024) { ok = false; break; }
        ok = ok && WriteExact(file, &nameChars, sizeof(nameChars)) &&
             WriteExact(file, &value.type, sizeof(value.type)) &&
             WriteExact(file, &dataBytes, sizeof(dataBytes)) &&
             WriteExact(file, value.name.c_str(), nameChars * sizeof(wchar_t));
        if (ok && dataBytes > 0) ok = WriteExact(file, value.data.data(), dataBytes);
        if (!ok) break;
    }
    CloseHandle(file);
    if (!ok) {
        DeleteFileW(path);
        MessageBoxW(owner, L"Yedek dosyası tam yazılamadı.", L"Yedekleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    MessageBoxW(owner, L"Ayar yedeği başarıyla oluşturuldu.", L"Yedekleme tamamlandı", MB_OK | MB_ICONINFORMATION | MB_TOPMOST);
    return true;
}

bool ImportSettingsBackup(HWND owner) {
    wchar_t path[MAX_PATH]{};
    OPENFILENAMEW dialog{};
    dialog.lStructSize = sizeof(dialog);
    dialog.hwndOwner = owner;
    dialog.lpstrFilter = L"Merlin ayar yedeği (*.mrb)\0*.mrb\0Tüm dosyalar (*.*)\0*.*\0\0";
    dialog.lpstrFile = path;
    dialog.nMaxFile = MAX_PATH;
    dialog.lpstrDefExt = L"mrb";
    dialog.Flags = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST | OFN_NOCHANGEDIR;
    if (!GetOpenFileNameW(&dialog)) return false; // Cancel is not an error.

    HANDLE file = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING,
                              FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        MessageBoxW(owner, L"Yedek dosyası açılamadı.", L"Geri yükleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    static constexpr char expectedMagic[8] = {'M','R','L','N','B','K','1','\0'};
    char magic[8]{};
    DWORD formatVersion = 0, count = 0;
    bool ok = ReadExact(file, magic, sizeof(magic)) &&
              ReadExact(file, &formatVersion, sizeof(formatVersion)) &&
              ReadExact(file, &count, sizeof(count)) &&
              std::memcmp(magic, expectedMagic, sizeof(magic)) == 0 &&
              formatVersion == 1 && count <= 256;
    std::vector<BackupRegistryValue> values;
    if (ok) values.reserve(count);
    for (DWORD i = 0; ok && i < count; ++i) {
        DWORD nameChars = 0, type = REG_NONE, dataBytes = 0;
        ok = ReadExact(file, &nameChars, sizeof(nameChars)) &&
             ReadExact(file, &type, sizeof(type)) &&
             ReadExact(file, &dataBytes, sizeof(dataBytes)) &&
             nameChars >= 1 && nameChars <= 512 && dataBytes <= 1024 * 1024;
        if (!ok) break;
        std::vector<wchar_t> name(nameChars, L'\0');
        ok = ReadExact(file, name.data(), nameChars * sizeof(wchar_t));
        if (!ok || name.back() != L'\0') { ok = false; break; }
        BackupRegistryValue value;
        value.name.assign(name.data());
        if (value.name.empty()) { ok = false; break; }
        value.type = type;
        value.data.resize(dataBytes);
        if (dataBytes > 0) ok = ReadExact(file, value.data.data(), dataBytes);
        if (ok) values.push_back(std::move(value));
    }
    CloseHandle(file);
    if (!ok) {
        MessageBoxW(owner, L"Dosya geçerli bir Merlin yedeği değil veya hasarlı.", L"Geri yükleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    const int confirm = MessageBoxW(owner,
        L"Mevcut Merlin ayarları bu yedekteki ayarlarla değiştirilsin mi?",
        L"Ayarları geri yükle", MB_YESNO | MB_ICONQUESTION | MB_TOPMOST | MB_SETFOREGROUND);
    if (confirm != IDYES) return false;

    HKEY key = nullptr;
    if (RegCreateKeyExW(HKEY_CURRENT_USER, kPreferencesRegistryKey, 0, nullptr, 0,
                        KEY_QUERY_VALUE | KEY_SET_VALUE, nullptr, &key, nullptr) != ERROR_SUCCESS) {
        MessageBoxW(owner, L"Ayar kayıt defteri açılamadı.", L"Geri yükleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
        return false;
    }
    // Clear only this mod's own preference values, then install the validated backup.
    for (;;) {
        wchar_t existingName[512]{};
        DWORD nameLen = 512;
        const LSTATUS status = RegEnumValueW(key, 0, existingName, &nameLen, nullptr, nullptr, nullptr, nullptr);
        if (status == ERROR_NO_MORE_ITEMS) break;
        if (status != ERROR_SUCCESS || RegDeleteValueW(key, existingName) != ERROR_SUCCESS) {
            RegCloseKey(key);
            MessageBoxW(owner, L"Mevcut ayarlar temizlenemedi; geri yükleme durduruldu.", L"Geri yükleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
            return false;
        }
    }
    for (const auto& value : values) {
        const BYTE* data = value.data.empty() ? nullptr : value.data.data();
        if (RegSetValueExW(key, value.name.c_str(), 0, value.type, data,
                           static_cast<DWORD>(value.data.size())) != ERROR_SUCCESS) {
            RegCloseKey(key);
            MessageBoxW(owner, L"Yedek ayarları kayıt defterine yazılamadı.", L"Geri yükleme başarısız", MB_OK | MB_ICONERROR | MB_TOPMOST);
            return false;
        }
    }
    RegCloseKey(key);
    LoadSettingsPreferences();
    g_canUndoGeneralSettings = false;
    g_generalScrollOffset = 0;
    g_currentIslandPage = IslandPageIdFromOrder(g_startPageOrder);
    g_previousIslandPage = g_currentIslandPage;
    g_pageIndicatorT = static_cast<float>(IslandPageOrderFromId(g_currentIslandPage));
    SetTimer(owner, kAnimationTimer, g_lowResourceMode ? 33 : 16, nullptr);
    g_lastVisibilityPolicyCheck = 0;
    g_firstFrame = true;
    Tick(owner);
    MessageBoxW(owner, L"Ayarlar yedekten geri yüklendi.", L"Geri yükleme tamamlandı", MB_OK | MB_ICONINFORMATION | MB_TOPMOST);
    return true;
}

